/**
 * populate.js — V3 full-coverage backend test-data generator.
 *
 * Purpose: emit at least one instance of EVERY event the backend indexer
 * dispatches (internal/indexer/cosmicgame/registry.go), except the groups
 * that are out of scope by design:
 *   - DAO / governance-contract events (next phase),
 *   - deploy-time-only events (Initialized, EIP712DomainChanged, Upgraded,
 *     AdminChanged — generated by the deploy / upgrade scripts),
 *   - V1/V2-legacy topics a V3 game cannot emit (BidPlaced V1,
 *     MainPrizeClaimed V1, CstRewardAmountForBiddingChanged,
 *     CstDutchAuctionDurationChanged, CstDutchAuctionDurationChangeDivisorChanged
 *     — the last two revert NotImplemented on V3),
 *   - forced error paths (FundTransferFailed, ERC20TransferFailed,
 *     EthTransferToCharityFailed) — intentionally skipped; note that
 *     ArbitrumError IS emitted incidentally on Hardhat because the ArbSys
 *     precompile does not exist there.
 *
 * Every admin numeric parameter is set twice (a large-but-BIGINT-safe extreme,
 * then the original value restored) so the backend sees value variation;
 * address parameters are re-set to their current value (event fires, state
 * unchanged), except the PrizesWallet which is genuinely replaced near the end
 * to exercise the indexer's dynamic prizes-wallet sources and the historic
 * wallets list in the API.
 *
 * Scenario dimensions beyond event existence:
 *   - a round claimed by a NON-last-bidder after timeoutDurationToClaimMainPrize,
 *   - prize withdrawal of another winner's balance after the withdrawal timeout,
 *   - donated token/NFT claimed by a NON-winner after the withdrawal timeout,
 *   - repeated same-token donation in one round (amount accumulation),
 *   - a round with mainPrizeNumCosmicSignatureNfts = 2 (multi-NFT main prize),
 *   - batch claims (claimManyDonatedTokens/Nfts, withdrawEthMany, stakeMany,
 *     unstakeMany, payManyRewards), plain ERC20/ERC721 transfers and approvals.
 *
 * At the end the script prints an event tally and FAILS (exit 1) if any
 * expected event was never emitted, so coverage regressions are loud.
 *
 * Run (deploy first; see deploy-and-populate.sh):
 *   CADDR=0x... [TSAMP1=0x... TSAMP2=0x...] \
 *   NODE_PATH=$COSMIC_SIGNATURE_DIR/node_modules npx hardhat run populate.js --network ...
 */
const { ethers } = require("hardhat");
require("./rpc-helpers.js");

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
async function customGetSigners() {
    const privateKeys = [
        "0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80",
        "0x59c6995e998f97a5a0044966f0945389dc9e86dae88c7a8412f4603b6b78690d",
        "0x5de4111afa1a4b94908f83103eb1f1706367c2e68ca870fc3fb9a804cdab365a",
        "0x7c852118294e51e653712a81e05800f419141751be58f605c371e15141b007a6",
        "0x47e179ec197488593b187f80a00eb0da91f1b9d0b13f8733639f19c30a34926a",
        "0x8b3a350cf5c34c9194ca85829a2df0ec3153be0318b5e2d3348e872092edffba"
    ];
    const signers = privateKeys.map(key => new ethers.Wallet(key, ethers.provider));
    const signerMap = {};
    for (const signer of signers) {
        signerMap[(await signer.getAddress()).toLowerCase()] = signer;
    }
    return { signers, signerMap };
}

function sleep(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }

async function increaseTime(seconds) {
    if (seconds <= 0) return;
    try {
        await ethers.provider.send("evm_increaseTime", [Math.ceil(seconds)]);
        await ethers.provider.send("evm_mine", []);
    } catch (e) {
        console.log("evm_increaseTime unavailable, sleeping " + seconds + "s:", e.message);
        await sleep(seconds * 1000);
    }
}

async function waitUntilPrizeTimeZero(game) {
    let t = Number(await game.getDurationUntilMainPrize());
    if (t > 0) await increaseTime(t + 1);
}

/** After a claim the next round has an activation delay; advance past it. */
async function advanceToNextRoundActive(game) {
    const activationTime = Number(await game.roundActivationTime());
    const block = await ethers.provider.getBlock("latest");
    const need = activationTime - Number(block.timestamp);
    if (need > 0) await increaseTime(need + 1);
}

/** Advance time until the CST Dutch-auction price is affordable for bidder. */
async function waitUntilCstPriceAffordable(game, cosmicToken, bidderAddress) {
    for (let i = 0; i < 1000; i++) {
        const price = await game.getNextCstBidPrice();
        const balance = await cosmicToken.balanceOf(bidderAddress);
        if (price <= balance) return;
        await increaseTime(60);
    }
    throw new Error("CST price never became affordable for " + bidderAddress);
}

// ---------------------------------------------------------------------------
// Run state: receipts for the final event tally, and step failure accounting
// ---------------------------------------------------------------------------
const allReceipts = [];
const failedSteps = [];
let currentStep = "(init)";

/** Wait for a tx and record its receipt for the coverage tally. */
async function TX(txPromise) {
    const tx = await txPromise;
    const receipt = await tx.wait();
    allReceipts.push(receipt);
    return receipt;
}

/** Run one named section; a failure is recorded and the run continues. */
async function step(name, fn) {
    currentStep = name;
    console.log("\n=== " + name + " ===");
    try {
        await fn();
        console.log("--- " + name + ": done");
    } catch (e) {
        console.error("--- " + name + ": FAILED: " + (e.message || e));
        if (e.stack) console.error(e.stack.split("\n").slice(0, 6).join("\n"));
        failedSteps.push({ name, error: (e.message || String(e)).slice(0, 300) });
    }
}

/** All logs in recorded receipts matching an event of iface emitted by addr. */
function recordedEvents(iface, eventName, emitterAddr) {
    const topic = iface.getEvent(eventName).topicHash;
    const addr = emitterAddr.toLowerCase();
    const out = [];
    for (const r of allReceipts) {
        for (const log of r.logs) {
            if (log.topics[0] === topic && log.address.toLowerCase() === addr) {
                out.push(iface.parseLog(log));
            }
        }
    }
    return out;
}

function eventsIn(receipt, iface, eventName, emitterAddr) {
    const topic = iface.getEvent(eventName).topicHash;
    const addr = emitterAddr.toLowerCase();
    return receipt.logs
        .filter(l => l.topics[0] === topic && l.address.toLowerCase() === addr)
        .map(l => iface.parseLog(l));
}

// ---------------------------------------------------------------------------
// Contract setup
// ---------------------------------------------------------------------------
async function getGame() {
    const addr = process.env.CADDR;
    if (typeof addr === "undefined" || addr.length !== 42) {
        console.log("CADDR environment variable does not contain the CosmicSignatureGame proxy address.");
        process.exit(1);
    }
    // Attach the newest game ABI available (mainnet proxy runs V3).
    for (const name of ["CosmicSignatureGameV3", "CosmicSignatureGameV2", "CosmicSignatureGame"]) {
        try { return await ethers.getContractAt(name, addr); } catch (e) { /* not in this repo */ }
    }
    throw new Error("No CosmicSignatureGame artifact found");
}

/**
 * Two sample ERC20s for donation testing. Uses TSAMP1/TSAMP2 when set;
 * otherwise deploys "Samp" or, if the repo lacks it, "FuzzTestMockErc20"
 * (present in the V3 deployment repo) and mints balances to the donors.
 */
async function getERC20SampleContracts(deployer, donors) {
    const a1 = process.env.TSAMP1, a2 = process.env.TSAMP2;
    const supply = ethers.parseEther("1000000");
    let tokens = null;
    if (typeof a1 === "string" && a1.length === 42 && typeof a2 === "string" && a2.length === 42) {
        for (const name of ["Samp", "FuzzTestMockErc20"]) {
            try {
                const t1 = await ethers.getContractAt(name, a1);
                await t1.totalSupply();
                tokens = [t1, await ethers.getContractAt(name, a2)];
                break;
            } catch (e) { /* try next artifact name */ }
        }
    }
    if (!tokens) {
        let factory;
        try { factory = await ethers.getContractFactory("Samp"); }
        catch (e) { factory = await ethers.getContractFactory("FuzzTestMockErc20"); }
        tokens = [];
        for (let i = 0; i < 2; i++) {
            const t = await factory.connect(deployer).deploy();
            await t.waitForDeployment();
            tokens.push(t);
        }
    }
    // Fund the donors from whatever source the token supports: open mint()
    // (FuzzTestMockErc20) or a transfer out of the deployer's premine (Samp).
    for (const t of tokens) {
        for (const d of donors) {
            const dAddr = await d.getAddress();
            if ((await t.balanceOf(dAddr)) >= supply / 2n) continue;
            try {
                await TX(t.connect(deployer).mint(dAddr, supply));
            } catch (e) {
                await TX(t.connect(deployer).transfer(dAddr, supply));
            }
        }
    }
    console.log("Sample ERC20s:", await tokens[0].getAddress(), await tokens[1].getAddress());
    return tokens;
}

async function mintRwalk(randomWalkNFT, signer) {
    const tokenPrice = await randomWalkNFT.getMintPrice();
    const receipt = await TX(randomWalkNFT.connect(signer).mint({ value: tokenPrice, gasLimit: 1000000 }));
    const parsed = eventsIn(receipt, randomWalkNFT.interface, "MintEvent", await randomWalkNFT.getAddress());
    return parsed[0].args[0];
}

/** Dump the SQL INSERT for cg_contracts (same format the backend expects). */
async function printCgContractsInsert(c) {
    const EIP1967_IMPL_SLOT = "0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc";
    let implementationAddr = "0x0000000000000000000000000000000000000000";
    try {
        const implBytes = await ethers.provider.getStorage(await c.game.getAddress(), EIP1967_IMPL_SLOT);
        implementationAddr = (ethers.AbiCoder.defaultAbiCoder().decode(["address"], implBytes))[0];
    } catch (e) {}
    console.log("");
    console.log("CosmicGame main contract:", await c.game.getAddress());
    console.log("-- SQL INSERT for cg_contracts (cosmic_game_addr, cosmic_signature_addr, cosmic_token_addr, cosmic_dao_addr, charity_wallet_addr, prizes_wallet_addr, random_walk_addr, staking_wallet_cst_addr, staking_wallet_rwalk_addr, marketing_wallet_addr, implementation_addr):");
    console.log(
        "INSERT INTO cg_contracts VALUES(" +
        `'${await c.game.getAddress()}',` +
        `'${await c.nft.getAddress()}',` +
        `'${await c.token.getAddress()}',` +
        `'${c.daoAddr}',` +
        `'${await c.charityWallet.getAddress()}',` +
        `'${await c.prizesWallet.getAddress()}',` +   // the ORIGINAL wallet; the replacement arrives via PrizesWalletAddressChanged
        `'${await c.randomWalkNFT.getAddress()}',` +
        `'${await c.stakingCst.getAddress()}',` +
        `'${await c.stakingRwalk.getAddress()}',` +
        `'${c.marketingAddr}',` +
        `'${implementationAddr}')`
    );
    console.log("");
}

// ---------------------------------------------------------------------------
// Round primitives
// ---------------------------------------------------------------------------
async function ethBid(game, signer, message, rwalkId = -1) {
    const bidPrice = await game.getNextEthBidPrice();
    // V2+/V3 signature: bidWithEth(randomWalkNftId, message, bidCstRewardAmountMinLimit)
    return await TX(game.connect(signer).bidWithEth(rwalkId, message, 0, { value: (bidPrice * 125n) / 100n, gasLimit: 1500000 }));
}

async function cstBid(game, token, signer, message) {
    await waitUntilCstPriceAffordable(game, token, await signer.getAddress());
    const cstPrice = await game.getNextCstBidPrice();
    return await TX(game.connect(signer).bidWithCst(cstPrice, message, 0, { gasLimit: 1500000 }));
}

async function claimBy(game, signer) {
    await waitUntilPrizeTimeZero(game);
    const roundNum = await game.roundNum();
    const receipt = await TX(game.connect(signer).claimMainPrize({ gasLimit: 12000000 }));
    await advanceToNextRoundActive(game);
    return { roundNum, receipt };
}

/**
 * Open a long "round inactive" window (admin setters are _onlyRoundIsInactive)
 * right after a claim, run fn, then reactivate the round. Must be called
 * before any bid lands in the new round (_onlyBeforeBidPlacedInRound).
 */
async function inInactiveWindow(game, owner, fn) {
    const block = await ethers.provider.getBlock("latest");
    await TX(game.connect(owner).setRoundActivationTime(Number(block.timestamp) + 1000000, { gasLimit: 1000000 }));
    try {
        await fn();
    } finally {
        const b2 = await ethers.provider.getBlock("latest");
        await TX(game.connect(owner).setRoundActivationTime(Number(b2.timestamp) + 2, { gasLimit: 1000000 }));
        await increaseTime(3);
    }
}

// ---------------------------------------------------------------------------
// Admin sweep: every V3 numeric param set to an extreme and restored, every
// address param re-set to its current value. Values stay BIGINT-safe (< 2^62)
// so the backend's integer columns see large-but-storable extremes.
// ---------------------------------------------------------------------------
const NUMERIC_PARAMS = [
    // [getterName, setterName, extremeValue]
    ["delayDurationBeforeRoundActivation", "setDelayDurationBeforeRoundActivation", 4611686018427387904n],
    ["ethDutchAuctionDurationDivisor", "setEthDutchAuctionDurationDivisor", 4611686018427387904n],
    ["ethDutchAuctionEndingBidPriceDivisor", "setEthDutchAuctionEndingBidPriceDivisor", 4611686018427387904n],
    ["ethBidPriceIncreaseDivisor", "setEthBidPriceIncreaseDivisor", 4611686018427387904n],
    ["ethBidRefundAmountInGasToSwallowMaxLimit", "setEthBidRefundAmountInGasToSwallowMaxLimit", 4611686018427387904n],
    // cstDutchAuctionDurationDivisor and bidCstRewardAmount are V1-only (their
    // setters were removed in V2; the V2 CST-auction setters revert NotImplemented on V3).
    ["cstDutchAuctionBeginningBidPriceMinLimit", "setCstDutchAuctionBeginningBidPriceMinLimit", 4611686018427387904n],
    ["bidMessageLengthMaxLimit", "setBidMessageLengthMaxLimit", 4611686018427387904n],
    ["bidCstRewardAmountMultiplier", "setBidCstRewardAmountMultiplier", 4611686018427387904n],
    ["cstPrizeAmount", "setCstPrizeAmount", 4611686018427387904n],
    ["chronoWarriorEthPrizeAmountPercentage", "setChronoWarriorEthPrizeAmountPercentage", 99n],
    ["raffleTotalEthPrizeAmountForBiddersPercentage", "setRaffleTotalEthPrizeAmountForBiddersPercentage", 99n],
    ["numRaffleEthPrizesForBidders", "setNumRaffleEthPrizesForBidders", 100n],
    ["numRaffleCosmicSignatureNftsForBidders", "setNumRaffleCosmicSignatureNftsForBidders", 100n],
    ["numRaffleCosmicSignatureNftsForRandomWalkNftStakers", "setNumRaffleCosmicSignatureNftsForRandomWalkNftStakers", 100n],
    ["cosmicSignatureNftStakingTotalEthRewardAmountPercentage", "setCosmicSignatureNftStakingTotalEthRewardAmountPercentage", 99n],
    ["initialDurationUntilMainPrizeDivisor", "setInitialDurationUntilMainPrizeDivisor", 4611686018427387904n],
    ["mainPrizeTimeIncrementInMicroSeconds", "setMainPrizeTimeIncrementInMicroSeconds", 4611686018427387904n],
    ["mainPrizeTimeIncrementIncreaseDivisor", "setMainPrizeTimeIncrementIncreaseDivisor", 4611686018427387904n],
    ["timeoutDurationToClaimMainPrize", "setTimeoutDurationToClaimMainPrize", 4611686018427387904n],
    ["mainEthPrizeAmountPercentage", "setMainEthPrizeAmountPercentage", 99n],
    ["charityEthDonationAmountPercentage", "setCharityEthDonationAmountPercentage", 99n],
    ["marketingWalletCstContributionAmount", "setMarketingWalletCstContributionAmount", 4611686018427387904n],
    ["cstBidPriceDeclineMultiplier", "setCstBidPriceDeclineMultiplier", 4611686018427387904n],
    ["cstBidPriceDeclineMultiplierChangeDivisor", "setCstBidPriceDeclineMultiplierChangeDivisor", 4611686018427387904n],
    ["roundLateBidDurationDivisor", "setRoundLateBidDurationDivisor", 4611686018427387904n],
    ["roundLateBidPricePremiumAmountBaseMultiplier", "setRoundLateBidPricePremiumAmountBaseMultiplier", 4611686018427387904n],
    ["roundLateBidPricePremiumAmountExponent", "setRoundLateBidPricePremiumAmountExponent", 7n],
    // mainPrizeNumCosmicSignatureNfts is handled separately (kept at 2 for one
    // round to exercise the multi-NFT main prize, restored by a later sweep).
];

const ADDRESS_PARAMS = [
    // [getterName, setterName] — re-set to the current value (event, no state change)
    ["token", "setCosmicSignatureToken"],
    ["randomWalkNft", "setRandomWalkNft"],
    ["nft", "setCosmicSignatureNft"],
    ["stakingWalletRandomWalkNft", "setStakingWalletRandomWalkNft"],
    ["stakingWalletCosmicSignatureNft", "setStakingWalletCosmicSignatureNft"],
    ["marketingWallet", "setMarketingWallet"],
    ["charityAddress", "setCharityAddress"],
    // prizesWallet is genuinely replaced in its own section.
];

async function adminSweep(game, owner) {
    const g = { gasLimit: 1000000 };
    for (const [getter, setter, extreme] of NUMERIC_PARAMS) {
        const original = await game[getter]();
        try {
            await TX(game.connect(owner)[setter](extreme, g));
            await TX(game.connect(owner)[setter](original, g));
        } catch (e) {
            // An extreme a validator rejects still needs the event: nudge by +1.
            console.log(setter + "(extreme) rejected, using original+1:", (e.message || e).slice(0, 120));
            await TX(game.connect(owner)[setter](original + 1n, g));
            await TX(game.connect(owner)[setter](original, g));
        }
    }
    for (const [getter, setter] of ADDRESS_PARAMS) {
        const current = await game[getter]();
        await TX(game.connect(owner)[setter](current, g));
    }
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
async function main() {
    const { signers, signerMap } = await customGetSigners();
    const [owner, addr1, addr2, addr3, addr4, addr5] = signers;

    const game = await getGame();
    const gameAddr = await game.getAddress();
    console.log("CosmicSignatureGame proxy:", gameAddr);

    const nft = await ethers.getContractAt("CosmicSignatureNft", await game.nft());
    const token = await ethers.getContractAt("CosmicSignatureToken", await game.token());
    const randomWalkNFT = await ethers.getContractAt("RandomWalkNFT", await game.randomWalkNft());
    const stakingCst = await ethers.getContractAt("StakingWalletCosmicSignatureNft", await game.stakingWalletCosmicSignatureNft());
    const stakingRwalk = await ethers.getContractAt("StakingWalletRandomWalkNft", await game.stakingWalletRandomWalkNft());
    const charityWallet = await ethers.getContractAt("CharityWallet", await game.charityAddress());
    const prizesWallet = await ethers.getContractAt("PrizesWallet", await game.prizesWallet());
    const marketingAddr = await game.marketingWallet();
    const marketingWallet = await ethers.getContractAt("MarketingWallet", marketingAddr);
    // The V3 game does not reference the DAO; try the legacy getters for the
    // cg_contracts dump and fall back to zero (DAO events are next phase).
    let daoAddr = "0x0000000000000000000000000000000000000000";
    try { daoAddr = await game.cosmicDAO(); } catch (e) {
        try { daoAddr = await game.dao(); } catch (e2) {}
    }

    const prizesWalletAddr = await prizesWallet.getAddress();
    const nftAddr = await nft.getAddress();
    const tokenAddr = await token.getAddress();

    const [samp1, samp2] = await getERC20SampleContracts(owner, [owner, addr1, addr2, addr3]);
    const samp1Addr = await samp1.getAddress();
    const samp2Addr = await samp2.getAddress();

    // Make sure round 0 is active (deploy leaves a short activation delay).
    await advanceToNextRoundActive(game);
    let rn = await game.roundNum();
    console.log("Round num =", Number(rn));

    // Tracking state shared across steps.
    let namedTokenDone = false;
    let secondPrizesWallet = null;

    // -----------------------------------------------------------------------
    await step("S1: ETH donations", async () => {
        await TX(game.connect(addr5).donateEth({ value: ethers.parseEther("100") }));
        const info = '{"version":1,"title":"Hardhat donation","message":"Donation from HardHat","url":"http://hardhat.org"}';
        await TX(game.connect(addr4).donateEthWithInfo(info, { value: ethers.parseEther("60") }));
        const info2 = '{"version":1,"title":"ArtBlocks donation","message":"ArtBlocks platform donation","url":"https://www.artblocks.io"}';
        await TX(game.connect(addr2).donateEthWithInfo(info2, { value: ethers.parseEther("90") }));
    });

    // -----------------------------------------------------------------------
    await step("S2: round A — ETH bidding basics, claim, NFT rename", async () => {
        await ethBid(game, addr1, "bid 1");                      // FirstBidPlacedInRound
        await ethBid(game, addr2, "bid 2");
        await ethBid(game, addr1, "");                           // empty message
        const rwId = await mintRwalk(randomWalkNFT, owner);
        await ethBid(game, owner, "rwalk-discount bid", Number(rwId));
        await ethBid(game, addr3, "bid 3");
        await ethBid(game, addr1, "bid 4");
        const { roundNum, receipt } = await claimBy(game, addr1);
        console.log("Round", Number(roundNum), "claimed by addr1");

        // Rename a minted NFT twice (NftNameChanged with and without rename).
        const mints = eventsIn(receipt, nft.interface, "NftMinted", nftAddr)
            .filter(ev => ev.args.nftOwnerAddress.toLowerCase() === addr1.address.toLowerCase());
        if (mints.length === 0) throw new Error("no NFT minted for claimer addr1");
        const tokenId = mints[0].args.nftId;
        await TX(nft.connect(addr1).setNftName(tokenId, "name 0", { gasLimit: 1000000 }));
        await TX(nft.connect(addr1).setNftName(tokenId, "name after 0", { gasLimit: 1000000 }));
        namedTokenDone = true;
    });

    // -----------------------------------------------------------------------
    await step("S3: admin sweep (all setters, extremes + restore)", async () => {
        await inInactiveWindow(game, owner, async () => {
            await adminSweep(game, owner);
            // Multi-NFT main prize for the NEXT round; restored in S5.
            await TX(game.connect(owner).setMainPrizeNumCosmicSignatureNfts(2n, { gasLimit: 1000000 }));
            // Satellite-contract admin events.
            const g = { gasLimit: 1000000 };
            await TX(charityWallet.connect(owner).setCharityAddress(await charityWallet.charityAddress(), g));
            await TX(marketingWallet.connect(owner).setTreasurerAddress(addr5.address, g));
            await TX(nft.connect(owner).setNftBaseUri("http://localhost/nft/base/", g));
            await TX(nft.connect(owner).setNftGenerationScriptUri("ipfs://cosmic-script-v3-test", g));
            // Short withdrawal timeout so the timeout sections stay fast.
            await TX(prizesWallet.connect(owner).setTimeoutDurationToWithdrawPrizes(600, g));
            // OwnershipTransferred round-trip on the least entangled ownable.
            await TX(charityWallet.connect(owner).transferOwnership(addr1.address, g));
            await TX(charityWallet.connect(addr1).transferOwnership(owner.address, g));
        });
    });

    // -----------------------------------------------------------------------
    await step("S4: round B — donations (tokens + NFTs), CST bids, batch claims", async () => {
        const g = { gasLimit: 1500000 };
        const big = ethers.parseEther("999999999");
        for (const s of [owner, addr1, addr2, addr3]) {
            await TX(samp1.connect(s).approve(prizesWalletAddr, big));
            await TX(samp2.connect(s).approve(prizesWalletAddr, big));
        }

        // Same token donated twice in one round: the wallet accumulates.
        let bidPrice = await game.getNextEthBidPrice();
        await TX(game.connect(owner).bidWithEthAndDonateToken(-1, "bid&donate samp1 #1", 0, samp1Addr, ethers.parseEther("10"), { value: (bidPrice * 125n) / 100n, ...g }));
        bidPrice = await game.getNextEthBidPrice();
        await TX(game.connect(owner).bidWithEthAndDonateToken(-1, "bid&donate samp1 #2", 0, samp1Addr, ethers.parseEther("5"), { value: (bidPrice * 125n) / 100n, ...g }));
        bidPrice = await game.getNextEthBidPrice();
        await TX(game.connect(addr1).bidWithEthAndDonateToken(-1, "bid&donate samp2", 0, samp2Addr, ethers.parseEther("7"), { value: (bidPrice * 125n) / 100n, ...g }));

        // NFT donations with an ETH bid.
        for (const s of [addr1, addr2]) {
            const rwId = await mintRwalk(randomWalkNFT, s);
            await TX(randomWalkNFT.connect(s).setApprovalForAll(prizesWalletAddr, true));
            bidPrice = await game.getNextEthBidPrice();
            await TX(game.connect(s).bidWithEthAndDonateNft(-1, "donated rwalk " + rwId, 0, await randomWalkNFT.getAddress(), rwId, { value: (bidPrice * 125n) / 100n, ...g }));
        }

        // RandomWalk-discount bids combined with donations in the same tx
        // (BidPlaced with rwalk id + TokenDonated / NftDonated together).
        const rwDiscT = await mintRwalk(randomWalkNFT, addr2);
        bidPrice = await game.getNextEthBidPrice();
        await TX(game.connect(addr2).bidWithEthAndDonateToken(rwDiscT, "rwalk-discount + token donation", 0, samp1Addr, ethers.parseEther("2"), { value: (bidPrice * 125n) / 100n, ...g }));
        const rwDiscN = await mintRwalk(randomWalkNFT, addr2);
        const rwDonN = await mintRwalk(randomWalkNFT, addr2);
        bidPrice = await game.getNextEthBidPrice();
        await TX(game.connect(addr2).bidWithEthAndDonateNft(rwDiscN, "rwalk-discount + nft donation", 0, await randomWalkNFT.getAddress(), rwDonN, { value: (bidPrice * 125n) / 100n, ...g }));

        // CST bid family; addr3 earned CST from earlier bids.
        await cstBid(game, token, addr3, "plain CST bid");
        await waitUntilCstPriceAffordable(game, token, addr3.address);
        let cstPrice = await game.getNextCstBidPrice();
        await TX(game.connect(addr3).bidWithCstAndDonateToken(cstPrice, "CST bid + samp2 donation", 0, samp2Addr, ethers.parseEther("3"), g));
        const rwId3 = await mintRwalk(randomWalkNFT, addr3);
        await TX(randomWalkNFT.connect(addr3).setApprovalForAll(prizesWalletAddr, true));
        await waitUntilCstPriceAffordable(game, token, addr3.address);
        cstPrice = await game.getNextCstBidPrice();
        await TX(game.connect(addr3).bidWithCstAndDonateNft(cstPrice, "CST bid + rwalk donation", 0, await randomWalkNFT.getAddress(), rwId3, g));

        // Last bid is CST -> LastCstBidderPrizePaid at claim; main prize mints
        // 2 NFTs (mainPrizeNumCosmicSignatureNfts=2 from S3).
        const { roundNum, receipt } = await claimBy(game, addr3);
        const round = roundNum;
        console.log("Round", Number(round), "claimed by addr3 (CST last bid, 2 main NFTs)");

        // Winner claims the donated prizes: one single claim, rest in batches.
        await TX(prizesWallet.connect(addr3).claimDonatedToken(round, samp1Addr, ethers.parseEther("17"), g));
        await TX(prizesWallet.connect(addr3).claimManyDonatedTokens([{ roundNum: round, tokenAddress: samp2Addr, amount: ethers.parseEther("10") }], g));
        const nftIdx = recordedEvents(prizesWallet.interface, "NftDonated", prizesWalletAddr)
            .filter(ev => ev.args.roundNum === round)
            .map(ev => ev.args.index);
        if (nftIdx.length < 3) throw new Error("expected >=3 donated NFTs in round " + round + ", got " + nftIdx.length);
        await TX(prizesWallet.connect(addr3).claimDonatedNft(nftIdx[0], g));
        await TX(prizesWallet.connect(addr3).claimManyDonatedNfts(nftIdx.slice(1), g));

        // ETH withdrawal by a raffle winner of this round (plain variant).
        const deposits = eventsIn(receipt, prizesWallet.interface, "EthReceived", prizesWalletAddr);
        if (deposits.length === 0) throw new Error("no PrizesWallet deposits in round " + round);
        const winnerAddr = deposits[0].args.prizeWinnerAddress;
        const winner = signerMap[winnerAddr.toLowerCase()];
        await TX(prizesWallet.connect(winner).getFunction("withdrawEth(uint256)")(round, g));
        // And the multi-round batch variant for another depositor if present.
        const other = deposits.map(d => d.args.prizeWinnerAddress).find(a => a.toLowerCase() !== winnerAddr.toLowerCase());
        if (other && signerMap[other.toLowerCase()]) {
            await TX(prizesWallet.connect(signerMap[other.toLowerCase()]).getFunction("withdrawEthMany(uint256[])")([round], g));
        }
    });

    // -----------------------------------------------------------------------
    await step("S5: restore mainPrizeNumCosmicSignatureNfts", async () => {
        await inInactiveWindow(game, owner, async () => {
            await TX(game.connect(owner).setMainPrizeNumCosmicSignatureNfts(1n, { gasLimit: 1000000 }));
        });
    });

    // -----------------------------------------------------------------------
    await step("S6: staking (CST + RWalk), reward deposit, unstake", async () => {
        // stakeMany/unstakeMany over many NFTs can exceed a small limit.
        const g = { gasLimit: 12000000 };
        const stakingCstAddr = await stakingCst.getAddress();
        const stakingRwalkAddr = await stakingRwalk.getAddress();

        // Stake every CS NFT our signers own: first singly, then stakeMany.
        const ts = Number(await nft.totalSupply());
        const byOwner = {};
        for (let i = 0; i < ts; i++) {
            const o = (await nft.ownerOf(i)).toLowerCase();
            if (signerMap[o]) (byOwner[o] = byOwner[o] || []).push(i);
        }
        let singleDone = false;
        for (const [o, ids] of Object.entries(byOwner)) {
            const s = signerMap[o];
            await TX(nft.connect(s).setApprovalForAll(stakingCstAddr, true, g));
            if (!singleDone) {
                await TX(stakingCst.connect(s).stake(ids[0], g));
                if (ids.length > 1) await TX(stakingCst.connect(s).stakeMany(ids.slice(1), g));
                singleDone = true;
            } else {
                await TX(stakingCst.connect(s).stakeMany(ids, g));
            }
        }

        // RandomWalk staking: mint fresh tokens and stake (single + many).
        const rwIds = [];
        for (let i = 0; i < 3; i++) rwIds.push(await mintRwalk(randomWalkNFT, addr2));
        await TX(randomWalkNFT.connect(addr2).setApprovalForAll(stakingRwalkAddr, true));
        await TX(stakingRwalk.connect(addr2).stake(rwIds[0], g));
        await TX(stakingRwalk.connect(addr2).stakeMany(rwIds.slice(1), g));

        // A round claimed while NFTs are staked: the staking wallet receives
        // its ETH share (EthDepositReceived) and RWalk stakers can win raffle NFTs.
        await ethBid(game, addr4, "staking round bid 1");
        await ethBid(game, addr5, "staking round bid 2");
        const { roundNum } = await claimBy(game, addr5);
        console.log("Round", Number(roundNum), "claimed with active stakers");

        // Unstake: one single, rest via unstakeMany (owner-grouped).
        const numActions = Number(await stakingCst.actionCounter());
        const cstActions = {};
        for (let i = 1; i <= numActions; i++) {
            const rec = (await stakingCst.stakeActions(i)).toObject();
            const o = rec.nftOwnerAddress.toLowerCase();
            if (rec.nftOwnerAddress !== "0x0000000000000000000000000000000000000000" && signerMap[o]) {
                (cstActions[o] = cstActions[o] || []).push(i);
            }
        }
        let cstSingleDone = false;
        for (const [o, ids] of Object.entries(cstActions)) {
            const s = signerMap[o];
            if (!cstSingleDone) {
                await TX(stakingCst.connect(s).unstake(ids[0], g));
                if (ids.length > 1) await TX(stakingCst.connect(s).unstakeMany(ids.slice(1), g));
                cstSingleDone = true;
            } else {
                await TX(stakingCst.connect(s).unstakeMany(ids, g));
            }
        }
        // RWalk unstake (addr2 owns all): single + many.
        const rwActions = [];
        const rwCount = Number(await stakingRwalk.actionCounter());
        for (let i = 0; i <= rwCount; i++) {
            try {
                const rec = (await stakingRwalk.stakeActions(i)).toObject();
                if (rec.nftOwnerAddress && rec.nftOwnerAddress.toLowerCase() === addr2.address.toLowerCase()) rwActions.push(i);
            } catch (e) {}
        }
        if (rwActions.length > 0) {
            await TX(stakingRwalk.connect(addr2).unstake(rwActions[0], g));
            if (rwActions.length > 1) await TX(stakingRwalk.connect(addr2).unstakeMany(rwActions.slice(1), g));
        }

        // Sweep any leftover staking-wallet balance to charity.
        await TX(stakingCst.connect(owner).tryPerformMaintenance(await charityWallet.getAddress(), g));
    });

    // -----------------------------------------------------------------------
    await step("S7: timeout paths (late claim, foreign withdrawals)", async () => {
        const g = { gasLimit: 12000000 };
        const gSmall = { gasLimit: 1500000 };

        // Round claimed by a NON-last-bidder after the claim timeout, with
        // unclaimed donations left behind for the second half of this step.
        await ethBid(game, addr1, "timeout round bid 1");
        let bidPrice = await game.getNextEthBidPrice();
        await TX(game.connect(addr2).bidWithEthAndDonateToken(-1, "timeout round samp1", 0, samp1Addr, ethers.parseEther("2"), { value: (bidPrice * 125n) / 100n, ...gSmall }));
        const rwId = await mintRwalk(randomWalkNFT, addr2);
        await TX(randomWalkNFT.connect(addr2).setApprovalForAll(prizesWalletAddr, true));
        bidPrice = await game.getNextEthBidPrice();
        await TX(game.connect(addr2).bidWithEthAndDonateNft(-1, "timeout round nft", 0, await randomWalkNFT.getAddress(), rwId, { value: (bidPrice * 125n) / 100n, ...gSmall }));

        await waitUntilPrizeTimeZero(game);
        const timeout = Number(await game.timeoutDurationToClaimMainPrize());
        await increaseTime(timeout + 2);
        const round = await game.roundNum();
        const receipt = await TX(game.connect(addr4).claimMainPrize(g));   // addr4 was not the last bidder
        await advanceToNextRoundActive(game);
        console.log("Round", Number(round), "claimed by NON-last-bidder addr4 after timeout");

        // Past the per-round withdrawal timeout: a non-winner takes the
        // donated prizes and another winner's ETH deposit.
        const wTimeout = Number(await prizesWallet.timeoutDurationToWithdrawPrizes());
        await increaseTime(wTimeout + 2);
        await TX(prizesWallet.connect(addr5).claimDonatedToken(round, samp1Addr, ethers.parseEther("2"), gSmall));
        const nftIdx = recordedEvents(prizesWallet.interface, "NftDonated", prizesWalletAddr)
            .filter(ev => ev.args.roundNum === round)
            .map(ev => ev.args.index);
        await TX(prizesWallet.connect(addr5).claimDonatedNft(nftIdx[0], gSmall));
        const deposits = eventsIn(receipt, prizesWallet.interface, "EthReceived", prizesWalletAddr);
        if (deposits.length > 0) {
            await TX(prizesWallet.connect(addr5).getFunction("withdrawEth(uint256,address)")(round, deposits[0].args.prizeWinnerAddress, gSmall));
        }
        // withdrawEverything(ethPrizeRoundNums[], donatedTokensToClaim[], donatedNftIndexes[]);
        // a zero ETH balance for the round is tolerated by the contract.
        await TX(prizesWallet.connect(addr4).withdrawEverything([round], [], [], gSmall));
    });

    // -----------------------------------------------------------------------
    await step("S8: marketing rewards and charity wallet flows", async () => {
        const g = { gasLimit: 1000000 };
        // Treasurer was changed to addr5 in S3, so addr5 pays the rewards.
        await TX(marketingWallet.connect(addr5).payReward(addr1.address, ethers.parseEther("7"), g));
        await TX(marketingWallet.connect(addr5).payReward(addr2.address, ethers.parseEther("2"), g));
        await TX(marketingWallet.connect(addr5).getFunction("payManyRewards(address[],uint256)")([addr3.address, addr4.address], ethers.parseEther("1"), g));
        // Treasurer back to the owner (second TreasurerAddressChanged), one more reward.
        await TX(marketingWallet.connect(owner).setTreasurerAddress(owner.address, g));
        await TX(marketingWallet.connect(owner).payReward(addr1.address, ethers.parseEther("3"), g));

        // Charity wallet: direct donation in, full send, partial send.
        await TX(addr2.sendTransaction({ to: await charityWallet.getAddress(), value: ethers.parseEther("4") }));
        await TX(charityWallet.connect(addr1).getFunction("send()")(g));
        await TX(addr3.sendTransaction({ to: await charityWallet.getAddress(), value: ethers.parseEther("2") }));
        await TX(charityWallet.connect(addr1).getFunction("send(uint256)")(ethers.parseEther("1"), g));
    });

    // -----------------------------------------------------------------------
    await step("S9: plain transfers, approvals, delegation", async () => {
        const g = { gasLimit: 1000000 };
        // ERC20: approval + plain transfer between EOAs (otype=0 in the backend).
        await TX(token.connect(addr1).approve(gameAddr, ethers.parseEther("10000000"), g));
        const bal = await token.balanceOf(addr1.address);
        if (bal > 0n) await TX(token.connect(addr1).transfer(addr2.address, bal / 10n, g));
        // Vote delegation (token-level events; the DAO itself is next phase).
        await TX(token.connect(addr1).delegate(addr1.address, g));
        await TX(token.connect(addr2).delegate(addr1.address, g));

        // ERC721: single-token approval + transfer between EOAs.
        const ts = Number(await nft.totalSupply());
        let moved = false;
        for (let i = 0; i < ts && !moved; i++) {
            const o = (await nft.ownerOf(i)).toLowerCase();
            const s = signerMap[o];
            if (!s) continue;
            await TX(nft.connect(s).approve(addr5.address, i, g));
            await TX(nft.connect(s).transferFrom(o, addr4.address, i, g));
            // The NEW owner renames the token it just received: rename rights
            // must follow ownership, and the API should attribute this
            // NftNameChanged to addr4, not the previous owner.
            await TX(nft.connect(addr4).setNftName(i, "renamed by new owner", g));
            moved = true;
        }
        if (!moved) throw new Error("no signer-owned CS NFT available for transfer");
    });

    // -----------------------------------------------------------------------
    await step("S10: PrizesWallet replacement + round on the new wallet", async () => {
        const g = { gasLimit: 1500000 };
        const PrizesWalletFactory = await ethers.getContractFactory("PrizesWallet");
        secondPrizesWallet = await PrizesWalletFactory.connect(owner).deploy(gameAddr);
        await secondPrizesWallet.waitForDeployment();
        const newAddr = await secondPrizesWallet.getAddress();
        await inInactiveWindow(game, owner, async () => {
            await TX(game.connect(owner).setPrizesWallet(newAddr, { gasLimit: 1000000 }));
            await TX(secondPrizesWallet.connect(owner).setTimeoutDurationToWithdrawPrizes(600, { gasLimit: 1000000 }));
        });
        console.log("PrizesWallet replaced:", prizesWalletAddr, "->", newAddr);

        // One round whose donations and deposits land in the NEW wallet.
        await TX(samp1.connect(owner).approve(newAddr, ethers.parseEther("999999999")));
        let bidPrice = await game.getNextEthBidPrice();
        await TX(game.connect(owner).bidWithEthAndDonateToken(-1, "donation to new wallet", 0, samp1Addr, ethers.parseEther("4"), { value: (bidPrice * 125n) / 100n, ...g }));
        const rwId = await mintRwalk(randomWalkNFT, addr1);
        await TX(randomWalkNFT.connect(addr1).setApprovalForAll(newAddr, true));
        bidPrice = await game.getNextEthBidPrice();
        await TX(game.connect(addr1).bidWithEthAndDonateNft(-1, "nft to new wallet", 0, await randomWalkNFT.getAddress(), rwId, { value: (bidPrice * 125n) / 100n, ...g }));
        const { roundNum } = await claimBy(game, addr1);
        console.log("Round", Number(roundNum), "ran on the new PrizesWallet");
        await TX(secondPrizesWallet.connect(addr1).claimDonatedToken(roundNum, samp1Addr, ethers.parseEther("4"), g));
        const idx = recordedEvents(secondPrizesWallet.interface, "NftDonated", newAddr)
            .filter(ev => ev.args.roundNum === roundNum).map(ev => ev.args.index);
        if (idx.length > 0) await TX(secondPrizesWallet.connect(addr1).claimDonatedNft(idx[0], g));
    });

    // -----------------------------------------------------------------------
    // Final report: cg_contracts INSERT, event tally, coverage assertion.
    // -----------------------------------------------------------------------
    await printCgContractsInsert({
        game, nft, token, charityWallet, prizesWallet, randomWalkNFT,
        stakingCst, stakingRwalk, daoAddr, marketingAddr,
    });

    // Expected events: [label, iface, eventName, emitterAddr].
    // Shared topic0s (Transfer, Approval, CharityAddressChanged, the
    // FundsTransferredToCharity/DonationSent pair) are disambiguated by the
    // emitter address, mirroring the backend registry's source filters.
    const expected = [
        ["BidPlaced (game)", game.interface, "BidPlaced", gameAddr],
        ["FirstBidPlacedInRound", game.interface, "FirstBidPlacedInRound", gameAddr],
        ["MainPrizeClaimed (V3)", game.interface, "MainPrizeClaimed", gameAddr],
        ["EthDonated", game.interface, "EthDonated", gameAddr],
        ["EthDonatedWithInfo", game.interface, "EthDonatedWithInfo", gameAddr],
        ["RaffleWinnerBidderEthPrizeAllocated", game.interface, "RaffleWinnerBidderEthPrizeAllocated", gameAddr],
        ["RaffleWinnerPrizePaid", game.interface, "RaffleWinnerPrizePaid", gameAddr],
        ["EnduranceChampionPrizePaid", game.interface, "EnduranceChampionPrizePaid", gameAddr],
        ["ChronoWarriorPrizePaid", game.interface, "ChronoWarriorPrizePaid", gameAddr],
        ["LastCstBidderPrizePaid", game.interface, "LastCstBidderPrizePaid", gameAddr],
        ["FundsTransferredToCharity (game)", game.interface, "FundsTransferredToCharity", gameAddr],
        ["NftMinted", nft.interface, "NftMinted", nftAddr],
        ["NftNameChanged", nft.interface, "NftNameChanged", nftAddr],
        ["Transfer (CS NFT)", nft.interface, "Transfer", nftAddr],
        ["Approval (CS NFT)", nft.interface, "Approval", nftAddr],
        ["ApprovalForAll (CS NFT)", nft.interface, "ApprovalForAll", nftAddr],
        ["NftBaseUriChanged", nft.interface, "NftBaseUriChanged", nftAddr],
        ["NftGenerationScriptUriChanged", nft.interface, "NftGenerationScriptUriChanged", nftAddr],
        ["Transfer (CST)", token.interface, "Transfer", tokenAddr],
        ["Approval (CST)", token.interface, "Approval", tokenAddr],
        ["DelegateChanged", token.interface, "DelegateChanged", tokenAddr],
        ["DelegateVotesChanged", token.interface, "DelegateVotesChanged", tokenAddr],
        ["EthReceived (PrizesWallet)", prizesWallet.interface, "EthReceived", prizesWalletAddr],
        ["EthWithdrawn (PrizesWallet)", prizesWallet.interface, "EthWithdrawn", prizesWalletAddr],
        ["TokenDonated", prizesWallet.interface, "TokenDonated", prizesWalletAddr],
        ["NftDonated", prizesWallet.interface, "NftDonated", prizesWalletAddr],
        ["DonatedTokenClaimed", prizesWallet.interface, "DonatedTokenClaimed", prizesWalletAddr],
        ["DonatedNftClaimed", prizesWallet.interface, "DonatedNftClaimed", prizesWalletAddr],
        ["TimeoutDurationToWithdrawPrizesChanged", prizesWallet.interface, "TimeoutDurationToWithdrawPrizesChanged", prizesWalletAddr],
        ["NftStaked (CST wallet)", stakingCst.interface, "NftStaked", await stakingCst.getAddress()],
        ["NftUnstaked (CST wallet)", stakingCst.interface, "NftUnstaked", await stakingCst.getAddress()],
        ["EthDepositReceived (CST staking)", stakingCst.interface, "EthDepositReceived", await stakingCst.getAddress()],
        ["NftStaked (RWalk wallet)", stakingRwalk.interface, "NftStaked", await stakingRwalk.getAddress()],
        ["NftUnstaked (RWalk wallet)", stakingRwalk.interface, "NftUnstaked", await stakingRwalk.getAddress()],
        ["DonationReceived (charity)", charityWallet.interface, "DonationReceived", await charityWallet.getAddress()],
        ["FundsTransferredToCharity (charity)", charityWallet.interface, "FundsTransferredToCharity", await charityWallet.getAddress()],
        ["CharityAddressChanged (charity wallet)", charityWallet.interface, "CharityAddressChanged", await charityWallet.getAddress()],
        ["OwnershipTransferred (charity wallet)", charityWallet.interface, "OwnershipTransferred", await charityWallet.getAddress()],
        ["RewardPaid (marketing)", marketingWallet.interface, "RewardPaid", marketingAddr],
        ["TreasurerAddressChanged", marketingWallet.interface, "TreasurerAddressChanged", marketingAddr],
        // Game admin events (one entry per ISystemEvents* event the sweep hits).
        ["DelayDurationBeforeRoundActivationChanged", game.interface, "DelayDurationBeforeRoundActivationChanged", gameAddr],
        ["RoundActivationTimeChanged", game.interface, "RoundActivationTimeChanged", gameAddr],
        ["EthDutchAuctionDurationDivisorChanged", game.interface, "EthDutchAuctionDurationDivisorChanged", gameAddr],
        ["EthDutchAuctionEndingBidPriceDivisorChanged", game.interface, "EthDutchAuctionEndingBidPriceDivisorChanged", gameAddr],
        ["EthBidPriceIncreaseDivisorChanged", game.interface, "EthBidPriceIncreaseDivisorChanged", gameAddr],
        ["EthBidRefundAmountInGasToSwallowMaxLimitChanged", game.interface, "EthBidRefundAmountInGasToSwallowMaxLimitChanged", gameAddr],
        // CstDutchAuctionDurationDivisorChanged and BidCstRewardAmountChanged are
        // V1-only (setters removed in V2+); they're in the legacy-excluded group.
        ["CstDutchAuctionBeginningBidPriceMinLimitChanged", game.interface, "CstDutchAuctionBeginningBidPriceMinLimitChanged", gameAddr],
        ["BidMessageLengthMaxLimitChanged", game.interface, "BidMessageLengthMaxLimitChanged", gameAddr],
        ["BidCstRewardAmountMultiplierChanged", game.interface, "BidCstRewardAmountMultiplierChanged", gameAddr],
        ["CstPrizeAmountChanged", game.interface, "CstPrizeAmountChanged", gameAddr],
        ["ChronoWarriorEthPrizeAmountPercentageChanged", game.interface, "ChronoWarriorEthPrizeAmountPercentageChanged", gameAddr],
        ["RaffleTotalEthPrizeAmountForBiddersPercentageChanged", game.interface, "RaffleTotalEthPrizeAmountForBiddersPercentageChanged", gameAddr],
        ["NumRaffleEthPrizesForBiddersChanged", game.interface, "NumRaffleEthPrizesForBiddersChanged", gameAddr],
        ["NumRaffleCosmicSignatureNftsForBiddersChanged", game.interface, "NumRaffleCosmicSignatureNftsForBiddersChanged", gameAddr],
        ["NumRaffleCosmicSignatureNftsForRandomWalkNftStakersChanged", game.interface, "NumRaffleCosmicSignatureNftsForRandomWalkNftStakersChanged", gameAddr],
        ["CosmicSignatureNftStakingTotalEthRewardAmountPercentageChanged", game.interface, "CosmicSignatureNftStakingTotalEthRewardAmountPercentageChanged", gameAddr],
        ["InitialDurationUntilMainPrizeDivisorChanged", game.interface, "InitialDurationUntilMainPrizeDivisorChanged", gameAddr],
        ["MainPrizeTimeIncrementInMicroSecondsChanged", game.interface, "MainPrizeTimeIncrementInMicroSecondsChanged", gameAddr],
        ["MainPrizeTimeIncrementIncreaseDivisorChanged", game.interface, "MainPrizeTimeIncrementIncreaseDivisorChanged", gameAddr],
        ["TimeoutDurationToClaimMainPrizeChanged", game.interface, "TimeoutDurationToClaimMainPrizeChanged", gameAddr],
        ["MainEthPrizeAmountPercentageChanged", game.interface, "MainEthPrizeAmountPercentageChanged", gameAddr],
        ["CharityEthDonationAmountPercentageChanged", game.interface, "CharityEthDonationAmountPercentageChanged", gameAddr],
        ["MarketingWalletCstContributionAmountChanged", game.interface, "MarketingWalletCstContributionAmountChanged", gameAddr],
        ["CstBidPriceDeclineMultiplierChanged", game.interface, "CstBidPriceDeclineMultiplierChanged", gameAddr],
        ["CstBidPriceDeclineMultiplierChangeDivisorChanged", game.interface, "CstBidPriceDeclineMultiplierChangeDivisorChanged", gameAddr],
        ["RoundLateBidDurationDivisorChanged", game.interface, "RoundLateBidDurationDivisorChanged", gameAddr],
        ["RoundLateBidPricePremiumAmountBaseMultiplierChanged", game.interface, "RoundLateBidPricePremiumAmountBaseMultiplierChanged", gameAddr],
        ["RoundLateBidPricePremiumAmountExponentChanged", game.interface, "RoundLateBidPricePremiumAmountExponentChanged", gameAddr],
        ["MainPrizeNumCosmicSignatureNftsChanged", game.interface, "MainPrizeNumCosmicSignatureNftsChanged", gameAddr],
        ["CosmicSignatureTokenAddressChanged", game.interface, "CosmicSignatureTokenAddressChanged", gameAddr],
        ["RandomWalkNftAddressChanged", game.interface, "RandomWalkNftAddressChanged", gameAddr],
        ["CosmicSignatureNftAddressChanged", game.interface, "CosmicSignatureNftAddressChanged", gameAddr],
        ["PrizesWalletAddressChanged", game.interface, "PrizesWalletAddressChanged", gameAddr],
        ["StakingWalletRandomWalkNftAddressChanged", game.interface, "StakingWalletRandomWalkNftAddressChanged", gameAddr],
        ["StakingWalletCosmicSignatureNftAddressChanged", game.interface, "StakingWalletCosmicSignatureNftAddressChanged", gameAddr],
        ["MarketingWalletAddressChanged", game.interface, "MarketingWalletAddressChanged", gameAddr],
        ["CharityAddressChanged (game)", game.interface, "CharityAddressChanged", gameAddr],
    ];
    if (secondPrizesWallet) {
        const newAddr = await secondPrizesWallet.getAddress();
        expected.push(
            ["EthReceived (PrizesWallet #2)", secondPrizesWallet.interface, "EthReceived", newAddr],
            ["TokenDonated (PrizesWallet #2)", secondPrizesWallet.interface, "TokenDonated", newAddr],
            ["DonatedTokenClaimed (PrizesWallet #2)", secondPrizesWallet.interface, "DonatedTokenClaimed", newAddr],
        );
    }
    // Environment-dependent: on Hardhat the ArbSys precompile is missing, so
    // claims emit ArbitrumError; on a real Arbitrum node they do not. WARN only.
    const expectedSoft = [
        ["ArbitrumError (hardhat only)", game.interface, "ArbitrumError", gameAddr],
    ];

    console.log("\n=== Event coverage ===");
    let missing = 0;
    for (const [label, iface, name, addr] of expected) {
        let n = 0;
        try { n = recordedEvents(iface, name, addr).length; }
        catch (e) { console.log(" ERROR | " + label + " | " + (e.message || e).slice(0, 100)); missing++; continue; }
        console.log((n > 0 ? "  ok   " : " MISSING") + "| " + String(n).padStart(4) + " | " + label);
        if (n === 0) missing++;
    }
    for (const [label, iface, name, addr] of expectedSoft) {
        let n = 0;
        try { n = recordedEvents(iface, name, addr).length; } catch (e) {}
        console.log((n > 0 ? "  ok   " : "  warn ") + "| " + String(n).padStart(4) + " | " + label);
    }

    console.log("\ntotal transactions recorded:", allReceipts.length);
    if (failedSteps.length > 0) {
        console.log("\nFAILED STEPS:");
        for (const f of failedSteps) console.log(" - " + f.name + ": " + f.error);
    }
    if (missing > 0) console.log("\nMISSING EVENTS: " + missing + " expected event type(s) were never emitted.");
    if (failedSteps.length > 0 || missing > 0) {
        console.log("POPULATE FAILED");
        process.exit(1);
    }
    console.log("POPULATE OK: all expected event types were emitted.");
}

main()
    .then(() => process.exit(0))
    .catch((error) => {
        console.error("populate.js aborted in step: " + currentStep);
        console.error(error);
        process.exit(1);
    });
